234:     const configuration: NewStatsConfiguration = await this.repository.readConfiguration();
235:     if (configuration.selectedMetric.length === 0) {
236:       return;
237:     }
238:     this.persistence['selectedMetric'] = configuration.selectedMetric;
239:     if (this.state['persistedMetric'] === undefined) {
