284:   /**
285:    * Rebuilds the starting window. A stored concrete range is preferred over
286:    * re-resolving the origin, so a restored screen shows the same dates the
287:    * user left, while the origin travels with them and keeps its meaning.
288:    */
289:   private restoreInitialPeriod(): NewStatsPeriod {
290:     const stored: Record<string, Object> = newStatsReadRecord(this.state, 'persistedPeriod');
291:     const storedStart: string = newStatsReadString(stored, 'start');
292:     const storedEnd: string = newStatsReadString(stored, 'end');
293:     const origin: string = this.initialPeriodOrigin();
294:     if (storedStart.length > 0 && storedEnd.length > 0 && origin.length > 0) {
295:       const kind: string = newStatsReadString(stored, 'kind');
296:       return {
297:         kind: kind.length > 0 ? kind : NewStatsPeriodKind.ROLLING,
298:         type: 'custom',
299:         origin: origin,
300:         start: storedStart,
301:         end: storedEnd
302:       };
303:     }
304:     const source: string = newStatsReadString(this.state, 'period');
305:     return resolveNewStatsPeriod(source.length > 0 ? source : NewStatsPeriodType.LAST_7_DAYS, this.today);
306:   }
