316:   private readCommittedPeriod(): NewStatsPeriod {
317:     const raw: Record<string, Object> = newStatsReadRecord(this.state, 'committedPeriod');
318:     const start: string = newStatsReadString(raw, 'start');
319:     const end: string = newStatsReadString(raw, 'end');
320:     const origin: string = newStatsReadString(raw, 'origin');
321:     const kind: string = newStatsReadString(raw, 'kind');
322:     if (start.length > 0 && end.length > 0) {
323:       return {
324:         kind: kind.length > 0 ? kind : NewStatsPeriodKind.CUSTOM,
325:         type: 'custom',
326:         origin: origin.length > 0 ? origin : newStatsReadString(this.state, 'period'),
327:         start: start,
328:         end: end
329:       };
330:     }
331:     const text: string = newStatsReadString(raw, 'type');
332:     const source: string = text.length > 0 ? text : newStatsReadString(this.state, 'period');
333:     return resolveNewStatsPeriod(source.length > 0 ? source : NewStatsPeriodType.LAST_7_DAYS, this.today);
334:   }
