354:   /**
355:    * An absent bucket selection is held as an empty record internally, because
356:    * the state container cannot hold a null. The published state renders it back
357:    * as an explicit null so consumers see "nothing selected" rather than an
358:    * empty selection object.
359:    */
360:   private clearBucketSelectionRecord(): void {
361:     const empty: Record<string, Object> = {};
362:     this.state['selectedBar'] = empty;
363:     this.state['hasSelectedBucket'] = false;
364:   }
