386:   /**
387:    * The five identity components the screen requires: surface, site, the
388:    * current day, the period, and the request variant.
389:    */
390:   private requestIdentityFor(surface: string): NewStatsRequestIdentity {
391:     const period: NewStatsPeriod = this.readEffectivePeriod();
392:     return {
393:       surface: surface,
394:       siteId: this.siteId,
395:       today: this.today,
396:       period: period.origin.length > 0 ? period.origin : NewStatsPeriodType.LAST_7_DAYS,
397:       variant: this.variant
398:     };
399:   }
400: 
401:   /**
402:    * Cache reuse must also not cross a date-window boundary, so the resolved
403:    * window is folded into the key even though the identity itself names only
404:    * the period.
405:    */
406:   private cacheKeyFor(surface: string): string {
407:     const identity: NewStatsRequestIdentity = this.requestIdentityFor(surface);
408:     const period: NewStatsPeriod = this.readEffectivePeriod();
409:     return newStatsRequestIdentityKey(identity) + '|' + period.start + '|' + period.end;
410:   }
