423:   // ------------------------------------------------------------------ chart
424: 
425:   private metricValue(point: Record<string, Object>, metric: string): number {
426:     const raw: Object | undefined = point[metric];
427:     if (raw === undefined || raw === null) {
428:       return 0;
429:     }
430:     return raw as number;
431:   }
432: 
433:   private bucketFromRecord(point: Record<string, Object>, index: number): NewStatsBucket {
434:     const rawPeriod: string = newStatsReadString(point, 'period');
435:     const upcomingFlag: boolean = newStatsReadBoolean(point, 'isUpcoming');
436:     const beyondToday: boolean = rawPeriod.length > 0 && diffNewStatsDays(this.today, rawPeriod) > 0;
437:     const upcoming: boolean = upcomingFlag || beyondToday;
438:     return {
439:       index: index,
440:       rawPeriod: rawPeriod,
441:       label: rawPeriod,
442:       isUpcoming: upcoming,
443:       canDrillDown: !upcoming && rawPeriod.length > 0,
444:       views: this.metricValue(point, NewStatsMetric.VIEWS),
445:       visitors: this.metricValue(point, NewStatsMetric.VISITORS),
446:       likes: this.metricValue(point, NewStatsMetric.LIKES),
447:       comments: this.metricValue(point, NewStatsMetric.COMMENTS),
448:       posts: this.metricValue(point, NewStatsMetric.POSTS)
449:     };
450:   }
451: 
452:   private bucketRecords(): Object[] {
453:     const current: Object[] = newStatsReadArray(this.state, 'currentPoints');
454:     if (current.length > 0) {
455:       return current;
456:     }
457:     const plain: Object[] = newStatsReadArray(this.state, 'points');
458:     if (plain.length > 0) {
459:       return plain;
460:     }
461:     return newStatsReadArray(newStatsReadRecord(this.state, 'loadedPeriodData'), 'points');
462:   }
463: 
464:   /**
465:    * Lays out one bucket per day of the window when the period response carried
466:    * no per-bucket rows. Days after today still occupy a slot so the chart has
467:    * the same shape all week, but they are marked as placeholders.
468:    */
469:   private synthesizedBuckets(): NewStatsBucket[] {
470:     const period: NewStatsPeriod = this.readCommittedPeriod();
471:     const span: number = diffNewStatsDays(period.start, period.end) + 1;
472:     const count: number = span > MAX_SYNTHESIZED_BUCKETS ? MAX_SYNTHESIZED_BUCKETS : span;
473:     const buckets: NewStatsBucket[] = [];
474:     for (let index: number = 0; index < count; index++) {
475:       const point: Record<string, Object> = {};
476:       point['period'] = addNewStatsDays(period.start, index);
477:       point[NewStatsMetric.VIEWS] = 0;
478:       point[NewStatsMetric.VISITORS] = 0;
479:       point[NewStatsMetric.LIKES] = 0;
480:       point[NewStatsMetric.COMMENTS] = 0;
481:       point[NewStatsMetric.POSTS] = 0;
482:       buckets.push(this.bucketFromRecord(point, index));
483:     }
484:     return buckets;
485:   }
486: 
487:   private buckets(): NewStatsBucket[] {
488:     const records: Object[] = this.bucketRecords();
489:     if (records.length === 0) {
490:       return this.synthesizedBuckets();
491:     }
492:     const buckets: NewStatsBucket[] = [];
493:     for (let index: number = 0; index < records.length; index++) {
494:       buckets.push(this.bucketFromRecord(records[index] as Record<string, Object>, index));
495:     }
496:     return buckets;
497:   }
498: 
499:   private selectedBucketIndex(): number {
500:     if (!this.hasBucketSelection()) {
501:       return -1;
502:     }
503:     const raw: Record<string, Object> = newStatsReadRecord(this.state, 'selectedBar');
504:     return newStatsReadNumber(raw, 'index');
505:   }
506: 
507:   private selectedBucket(): NewStatsBucket | undefined {
508:     if (!this.hasBucketSelection()) {
509:       return undefined;
510:     }
511:     const buckets: NewStatsBucket[] = this.buckets();
512:     const index: number = this.selectedBucketIndex();
513:     if (index < 0 || index >= buckets.length) {
514:       return undefined;
515:     }
516:     return buckets[index];
517:   }
518: 
519:   private bucketValue(bucket: NewStatsBucket, metric: string): number {
520:     if (metric === NewStatsMetric.VIEWS) {
521:       return bucket.views;
522:     }
523:     if (metric === NewStatsMetric.VISITORS) {
524:       return bucket.visitors;
525:     }
526:     if (metric === NewStatsMetric.LIKES) {
527:       return bucket.likes;
528:     }
529:     if (metric === NewStatsMetric.COMMENTS) {
530:       return bucket.comments;
531:     }
532:     return bucket.posts;
533:   }
534: 
535:   /**
536:    * Recomputes the chart surface from data already held for the committed
537:    * window. A metric change or a bucket tap both land here, which is why
538:    * neither of them needs a network round trip.
539:    */
540:   private recomputeChartSeries(): void {
541:     const period: NewStatsPeriod = this.readCommittedPeriod();
542:     const chosen: string = this.displayedMetric();
543:     const values: number[] = [];
544:     const buckets: NewStatsBucket[] = this.buckets();
545:     let elapsedCount: number = 0;
546:     let elapsedSum: number = 0;
547:     for (const bucket of buckets) {
548:       const value: number = this.bucketValue(bucket, chosen);
549:       values.push(value);
550:       if (!bucket.isUpcoming) {
551:         elapsedCount += 1;
552:         elapsedSum += value;
553:       }
554:     }
555:     this.state['chartPointValues'] = values;
556:     this.state['chartBuckets'] = this.encodedBuckets(buckets);
557:     this.state['futureBucketCount'] = buckets.length - elapsedCount;
558:     this.state['elapsedBucketCount'] = elapsedCount;
559:     this.state['elapsedBucketAverage'] = elapsedCount > 0 ? elapsedSum / elapsedCount : 0;
560: 
561:     const totals: Record<string, Object> = newStatsReadRecord(newStatsReadRecord(this.state, 'loadedPeriodData'),
562:       'totals');
563:     const total: Object | undefined = totals[chosen];
564:     const selected: NewStatsBucket | undefined = this.selectedBucket();
565:     if (selected !== undefined) {
566:       this.state['chartTotal'] = this.bucketValue(selected, chosen);
567:       this.state['chartRangeStart'] = selected.rawPeriod;
568:       this.state['chartRangeEnd'] = selected.rawPeriod;
569:     } else {
570:       this.state['chartTotal'] = total === undefined ? elapsedSum : (total as number);
571:       this.state['chartRangeStart'] = period.start;
572:       this.state['chartRangeEnd'] = period.end;
573:     }
574:     this.state['chartMetric'] = chosen;
575:     this.state['chartSeriesMetric'] = chosen;
576:     this.state['chartHourly'] = isHourlyNewStatsPeriod(period);
577:   }
578: 
579:   private encodedBuckets(buckets: NewStatsBucket[]): Object[] {
580:     const encoded: Object[] = [];
581:     for (const bucket of buckets) {
582:       const record: Record<string, Object> = {};
583:       record['index'] = bucket.index;
584:       record['rawPeriod'] = bucket.rawPeriod;
585:       record['isUpcoming'] = bucket.isUpcoming;
586:       record['canDrillDown'] = bucket.canDrillDown;
587:       record[NewStatsMetric.VIEWS] = bucket.views;
588:       record[NewStatsMetric.VISITORS] = bucket.visitors;
589:       record[NewStatsMetric.LIKES] = bucket.likes;
590:       record[NewStatsMetric.COMMENTS] = bucket.comments;
591:       record[NewStatsMetric.POSTS] = bucket.posts;
592:       encoded.push(record);
593:     }
594:     return encoded;
595:   }
