611:   private displayedMetricFor(period: NewStatsPeriod): string {
612:     const chosen: string = this.selectedMetric();
613:     if (supportsNewStatsChartMetric(period, chosen, this.hourlySeriesMetrics())) {
614:       return chosen;
615:     }
616:     return fallbackNewStatsMetric(period, this.hourlySeriesMetrics());
