619:   private syncChartStateAfterPeriodChange(explicitPick: boolean): void {
620:     const period: NewStatsPeriod = this.readCommittedPeriod();
621:     const chosen: string = this.selectedMetric();
622:     const drawable: boolean = supportsNewStatsChartMetric(period, chosen, this.hourlySeriesMetrics());
623:     this.state['displayedMetric'] = this.displayedMetricFor(period);
624:     this.state['supportedMetrics'] = supportedNewStatsChartMetrics(period, this.hourlySeriesMetrics());
625:     if (!drawable && explicitPick) {
626:       // The user asked for something this window cannot draw, so say so
627:       // rather than showing a chart for a different metric.
628:       this.state['chartState'] = NewStatsContentState.METRIC_UNAVAILABLE;
629:       this.state['unavailableMetric'] = chosen;
630:     } else if (this.state['chartState'] !== NewStatsContentState.ERROR) {
631:       this.state['chartState'] = NewStatsContentState.LOADED;
632:     }
