682:   /**
683:    * Applies a response only when it belongs to the current refresh boundary.
684:    * A result that started before the boundary is discarded rather than
685:    * repopulating refreshed state.
686:    */
687:   private async applyResponse(response: NewStatsRemoteResponse, event: Record<string, Object>): Promise<boolean> {
688:     if (!this.ledger.isCurrent(response.generation)) {
689:       await this.emit({
690:         name: 'discardStaleStatsResult',
691:         source: 'Index.NewStatsStore.ledger',
692:         siteId: this.siteId,
693:         channel: response.channel
694:       });
695:       this.ledger.finish(response.channel);
696:       return false;
697:     }
698:     this.ledger.finish(response.channel);
699:     if (response.channel === NEW_STATS_CHANNEL_REGION_VIEWS) {
700:       await this.applyRegionResponse(response, event);
701:       return true;
702:     }
703:     if (response.outcome === NEW_STATS_OUTCOME_SUCCESS) {
704:       this.applyStatsPayload(response.payload, response.channel, event);
705:       return true;
706:     }
707:     this.applyStatsFailure(response, response.outcome === NEW_STATS_OUTCOME_NETWORK_ERROR);
708:     return false;
709:   }
710: 
711:   private applyStatsPayload(payload: Record<string, Object>, channel: string, event: Record<string, Object>): void {
712:     const loaded: Record<string, Object> = newStatsReadRecord(payload, 'totals');
713:     if (Object.keys(loaded).length > 0) {
714:       const descriptor: Record<string, Object> = {};
715:       descriptor['totals'] = loaded;
716:       const points: Object[] = newStatsReadArray(payload, 'points');
717:       if (points.length > 0) {
718:         descriptor['points'] = points;
719:       }
720:       this.state['loadedPeriodData'] = descriptor;
721:     }
722:     const views: Object | undefined = payload[KEY_VIEWS];
723:     if (views !== undefined && views !== null) {
724:       this.state[KEY_VIEWS] = views as number;
725:       this.state['visibleViews'] = views as number;
726:     }
727:     this.state['chartState'] = NewStatsContentState.LOADED;
728:     this.state['loadingPlaceholderVisible'] = false;
729:     this.state['needsRevalidation'] = false;
730:     this.state['refreshing'] = false;
731:     this.state['backgroundRevalidationPending'] = false;
732:     this.recomputeChartSeries();
733:     // Only a response that actually carried data becomes the cached value, and
734:     // it is then marked as revalidated. An empty answer must not be cached, or
735:     // a cold start would look like a valid result on the next visit.
736:     if (Object.keys(payload).length > 0) {
737:       this.cache.write(this.cacheKeyFor(NEW_STATS_SURFACE_VIEWS_CHART),
738:         this.requestIdentityFor(NEW_STATS_SURFACE_VIEWS_CHART), this.cachePayload(), this.today, false);
739:       if (channel === NEW_STATS_CHANNEL_REFRESH) {
740:         this.state['cachedViewsForNextVisit'] = newStatsReadNumber(this.state, KEY_VIEWS);
741:       }
742:     }
743:     void event;
744:   }
745: 
746:   /** The cache holds the figures the screen would show for this window. */
747:   private cachePayload(): Record<string, Object> {
748:     const payload: Record<string, Object> = {};
749:     const totals: Record<string, Object> = newStatsReadRecord(newStatsReadRecord(this.state, 'loadedPeriodData'),
750:       'totals');
751:     const keys: string[] = Object.keys(totals);
752:     for (const key of keys) {
753:       payload[key] = totals[key];
754:     }
755:     payload[KEY_VIEWS] = newStatsReadNumber(this.state, KEY_VIEWS);
756:     return payload;
757:   }
758: 
759:   /**
760:    * A foreground failure stops loading and offers the ordinary retry. A
761:    * background revalidation failure keeps whatever cached content is already
762:    * usable and stays out of the way.
763:    */
764:   private applyStatsFailure(response: NewStatsRemoteResponse, offline: boolean): void {
765:     const key: string = this.cacheKeyFor(NEW_STATS_SURFACE_VIEWS_CHART);
766:     const cached: NewStatsCacheEntry | undefined = this.cache.read(key);
767:     this.state['backgroundRevalidationPending'] = false;
768:     if (response.channel === NEW_STATS_CHANNEL_REVALIDATION && cached !== undefined) {
769:       // The cached result stays exactly as it was, and stays revalidation-due.
770:       this.restoreCachedEntry(cached);
771:       this.state['chartState'] = NewStatsContentState.LOADED;
772:       this.state['loadingPlaceholderVisible'] = false;
773:       this.state['needsRevalidation'] = true;
774:       this.state['revalidationError'] = offline ? 'offline' : response.errorCode;
775:       this.cache.write(key, cached.identity, cached.payload, cached.storedOn, true);
776:       return;
777:     }
778:     if (cached !== undefined) {
779:       this.restoreCachedEntry(cached);
780:       this.state['needsRevalidation'] = true;
781:       return;
782:     }
783:     this.state['chartState'] = NewStatsContentState.ERROR;
784:     this.state['loadingPlaceholderVisible'] = false;
785:     this.state['refreshing'] = false;
786:     this.state['retryAvailable'] = true;
787:     this.state['lastError'] = offline ? 'offline' : response.errorCode;
788:   }
789: 
790:   private restoreCachedEntry(entry: NewStatsCacheEntry): void {
791:     const keys: string[] = Object.keys(entry.payload);
792:     for (const key of keys) {
793:       if (key === KEY_VIEWS) {
794:         continue;
795:       }
796:       this.state[key] = entry.payload[key];
797:     }
798:     const views: Object | undefined = entry.payload[KEY_VIEWS];
799:     if (views !== undefined && views !== null) {
800:       this.state[KEY_VIEWS] = views as number;
801:       this.state['visibleViews'] = views as number;
802:       this.state['cachedViewsForNextVisit'] = views as number;
803:     }
804:     this.state['loadingPlaceholderVisible'] = false;
805:     this.recomputeChartSeries();
806:   }
