808:   // ------------------------------------------------------------------- cache
809: 
810:   private adoptSeededCacheEntry(): void {
811:     const seededIdentity: Record<string, Object> = newStatsReadRecord(this.state, 'requestIdentity');
812:     const cached: Record<string, Object> = newStatsReadRecord(this.state, 'displayedCachedResult');
813:     const site: number = newStatsReadNumber(seededIdentity, 'siteId');
814:     const surface: string = newStatsReadString(seededIdentity, 'surface');
815:     const day: string = newStatsReadString(seededIdentity, 'today');
816:     const period: string = newStatsReadString(seededIdentity, 'period');
817:     const variant: string = newStatsReadString(seededIdentity, 'variant');
818:     const seededViews: number = newStatsReadNumber(cached, KEY_VIEWS);
819:     if (surface.length === 0 || Object.keys(cached).length === 0) {
820:       return;
821:     }
822:     const identity: NewStatsRequestIdentity = {
823:       surface: surface,
824:       siteId: site,
825:       today: day.length > 0 ? day : this.today,
826:       period: period,
827:       variant: variant
828:     };
829:     // Key the restored entry exactly the way a live lookup would, so a revisit
830:     // finds it without any special-casing.
831:     const entry: NewStatsCacheEntry = {
832:       key: this.cacheKeyFor(NEW_STATS_SURFACE_VIEWS_CHART),
833:       identity: identity,
834:       payload: cached,
835:       storedOn: day.length > 0 ? day : this.today,
836:       needsRevalidation: newStatsReadBoolean(this.state, 'needsRevalidation')
837:     };
838:     this.cache.adopt(entry);
839:     this.state[KEY_VIEWS] = seededViews;
840:     this.state['visibleViews'] = seededViews;
841:   }
