843:   private storeInCache(payload: Record<string, Object>): void {
844:     const key: string = this.cacheKeyFor(NEW_STATS_SURFACE_VIEWS_CHART);
845:     this.cache.write(key, this.requestIdentityFor(NEW_STATS_SURFACE_VIEWS_CHART), payload, this.today, false);
846:     const views: Object | undefined = payload[KEY_VIEWS];
847:     if (views !== undefined && views !== null) {
848:       this.state['cachedViewsForNextVisit'] = views as number;
849:     }
850:   }
