868:   private async dispatch(name: string, event: Record<string, Object>): Promise<void> {
869:     if (name === 'loadPeriodData') {
870:       await this.onLoadPeriodData(event);
871:       return;
872:     }
873:     if (name === 'selectMetric') {
874:       await this.onSelectMetric(event);
875:       return;
876:     }
877:     if (name === 'selectPeriod') {
878:       await this.onSelectPeriod(event);
879:       return;
880:     }
881:     if (name === 'tapChartBucket') {
882:       await this.onTapChartBucket(event);
883:       return;
884:     }
885:     if (name === 'drillIntoSelectedBucket') {
886:       await this.onDrillIntoSelectedBucket(event);
887:       return;
888:     }
889:     if (name === 'navigateBackward') {
890:       await this.onNavigateBackward(event);
891:       return;
892:     }
893:     if (name === 'navigateForwardAfterRestore') {
894:       await this.onNavigateForward(event);
895:       return;
896:     }
897:     if (name === 'navigateForward') {
898:       await this.onNavigateForward(event);
899:       return;
900:     }
901:     if (name === 'recreateStatsSurface') {
902:       await this.onRecreateStatsSurface(event);
903:       return;
904:     }
905:     if (name === 'revisitStatsSurface') {
906:       await this.onRevisitStatsSurface(event);
907:       return;
908:     }
909:     if (name === 'backgroundRevalidation' || name === 'backgroundRevalidationFailure') {
910:       await this.onBackgroundRevalidation(event);
911:       return;
912:     }
913:     if (name === 'retryBackgroundRevalidation') {
914:       await this.onRetryBackgroundRevalidation(event);
915:       return;
916:     }
917:     if (name === 'pullToRefresh') {
918:       await this.onPullToRefresh(event);
919:       return;
920:     }
921:     if (name === 'retry' || name === 'retryLoad') {
922:       await this.onRetry(event);
923:       return;
924:     }
925:     if (name === 'selectLocationType') {
926:       await this.onSelectLocationType(event);
927:       return;
928:     }
929:     if (name === 'openPlanAction') {
930:       await this.emit({ name: 'openPlanUpgrade', destination: this.planActionDestination() });
931:       return;
932:     }
