935:   private async fetchPeriodData(event: Record<string, Object>): Promise<void> {
936:     const generation: number = this.ledger.currentGeneration();
937:     this.state['periodFetchCount'] = newStatsReadNumber(this.state, 'periodFetchCount') + 1;
938:     this.state['loadingPlaceholderVisible'] = true;
939:     if (this.state['chartState'] !== NewStatsContentState.METRIC_UNAVAILABLE) {
940:       this.state['chartState'] = NewStatsContentState.LOADING;
941:     }
942:     this.state['refreshing'] = false;
943:     await this.emit({
944:       name: 'fetchStatsForPeriod',
945:       source: 'Index.NewStatsStore.period',
946:       siteId: this.siteId,
947:       selectedMetric: this.displayedMetric(),
948:       selectedPeriodType: this.readCommittedPeriod().origin,
949:       forceRefresh: newStatsReadBoolean(event, 'forceRefresh'),
950:       period: this.requestIdentityRecord(NEW_STATS_SURFACE_VIEWS_CHART)
951:     });
952:     const responses: NewStatsRemoteResponse[] = await this.request(NEW_STATS_CHANNEL_PERIOD_DATA,
953:       NEW_STATS_SURFACE_VIEWS_CHART, false, event, generation);
954:     for (const response of responses) {
955:       await this.applyResponse(response, event);
956:     }
957:   }
