963:   private async onSelectMetric(event: Record<string, Object>): Promise<void> {
964:     const metric: string = newStatsReadString(event, 'metric');
965:     if (metric.length === 0) {
966:       return;
967:     }
968:     this.state['selectedMetric'] = metric;
969:     // The preference is durable regardless of whether this window can draw it.
970:     this.state['persistedMetric'] = metric;
971:     this.state['metricPickedOnCurrentPeriod'] = true;
972:     this.persistence['selectedMetric'] = metric;
973:     this.syncChartStateAfterPeriodChange(true);
974:     await this.emit({ name: 'selectChartMetric', selectedMetric: metric, metric: metric, siteId: this.siteId });
975:     // The period response already carries every metric, so this only redraws.
976:     this.recomputeChartSeries();
977:   }
