979:   private async onSelectPeriod(event: Record<string, Object>): Promise<void> {
980:     const origin: string = newStatsReadString(event, 'period');
981:     if (origin.length === 0) {
982:       return;
983:     }
984:     const period: NewStatsPeriod = resolveNewStatsPeriod(origin, this.today);
985:     this.state['period'] = origin;
986:     this.commitPeriod(period);
987:     this.state['metricPickedOnCurrentPeriod'] = false;
988:     this.syncChartStateAfterPeriodChange(false);
989:     this.recomputeChartSeries();
990:     await this.emit({
991:       name: 'selectStatsPeriod',
992:       originPeriodType: this.readCommittedPeriod().origin,
993:       origin: origin,
994:       selectedPeriodType: origin,
995:       customStart: period.start,
996:       customEnd: period.end,
997:       siteId: this.siteId
998:     });
999:     await this.fetchPeriodData(event);
1000:   }
