1002:   /** Every committed period change invalidates any soft bucket selection. */
1003:   private commitPeriod(period: NewStatsPeriod): void {
1004:     this.writePeriod('committedPeriod', period);
1005:     this.writePeriod('effectivePeriod', period);
1006:     this.clearBucketSelectionRecord();
1007:     this.state['period'] = period.origin;
1008:     this.state['canNavigateForward'] = canPageNewStatsForward(period, this.today);
1009:     this.state['canNavigateBackward'] = true;
1010:     this.state['persistedOrigin'] = period.origin;
1011:     const persistedPeriod: Record<string, Object> = {};
1012:     persistedPeriod['type'] = 'custom';
1013:     persistedPeriod['start'] = period.start;
1014:     persistedPeriod['end'] = period.end;
1015:     this.state['persistedPeriod'] = persistedPeriod;
1016:     this.state['restoredOrigin'] = period.origin;
1017:     this.persistence['period'] = period.origin;
1018:     this.persistence['periodOrigin'] = period.origin;
1019:     this.persistence['periodStart'] = period.start;
1020:     this.persistence['periodEnd'] = period.end;
1021:     this.persistence['periodKind'] = period.kind;
1022:   }
