1024:   private async onTapChartBucket(event: Record<string, Object>): Promise<void> {
1025:     const index: number = newStatsReadNumber(event, 'index');
1026:     const buckets: NewStatsBucket[] = this.buckets();
1027:     const bucket: NewStatsBucket | undefined = this.resolveTapTarget(index, buckets);
1028:     if (bucket === undefined) {
1029:       // A placeholder for a bucket that has not happened yet is not actionable.
1030:       return;
1031:     }
1032:     if (this.selectedBucketIndex() === index) {
1033:       this.clearBucketSelection();
1034:       return;
1035:     }
1036:     const bar: Record<string, Object> = {};
1037:     bar['index'] = bucket.index;
1038:     bar['rawPeriod'] = bucket.rawPeriod;
1039:     bar['canDrillDown'] = bucket.canDrillDown;
1040:     this.setBucketSelectionRecord(bar);
1041:     const effective: NewStatsPeriod = {
1042:       kind: NewStatsPeriodKind.CUSTOM,
1043:       type: 'custom',
1044:       origin: 'custom',
1045:       start: bucket.rawPeriod,
1046:       end: bucket.rawPeriod
1047:     };
1048:     this.writePeriod('effectivePeriod', effective);
1049:     this.state['canDrillDown'] = bucket.canDrillDown;
1050:     this.recomputeChartSeries();
1051:     await this.emit({
1052:       name: 'chartBucketSelected',
1053:       siteId: this.siteId,
1054:       index: bucket.index,
1055:       rawPeriod: bucket.rawPeriod,
1056:       canDrillDown: bucket.canDrillDown
1057:     });
1058:   }
1059: 
1060:   private resolveTapTarget(index: number, buckets: NewStatsBucket[]): NewStatsBucket | undefined {
1061:     if (index >= 0 && index < buckets.length) {
1062:       const bucket: NewStatsBucket = buckets[index];
1063:       if (bucket.isUpcoming || bucket.rawPeriod.length === 0) {
1064:         return undefined;
1065:       }
1066:       return bucket;
1067:     }
1068:     return undefined;
1069:   }
1070: 
1071:   private clearBucketSelection(): void {
1072:     this.clearBucketSelectionRecord();
1073:     this.writePeriod('effectivePeriod', this.readCommittedPeriod());
1074:     this.state['canDrillDown'] = false;
1075:     this.recomputeChartSeries();
1076:   }
