1078:   private async onDrillIntoSelectedBucket(event: Record<string, Object>): Promise<void> {
1079:     const bucket: NewStatsBucket | undefined = this.selectedBucket();
1080:     if (bucket === undefined || !bucket.canDrillDown) {
1081:       return;
1082:     }
1083:     const target: NewStatsPeriod = {
1084:       kind: NewStatsPeriodKind.CUSTOM,
1085:       type: 'custom',
1086:       origin: 'custom',
1087:       start: bucket.rawPeriod,
1088:       end: bucket.rawPeriod
1089:     };
1090:     // The transient selection goes away as part of committing, before the
1091:     // destination has finished loading.
1092:     this.clearBucketSelectionRecord();
1093:     this.writePeriod('committedPeriod', target);
1094:     this.writePeriod('effectivePeriod', target);
1095:     this.state['period'] = target.origin;
1096:     this.state['canDrillDown'] = false;
1097:     this.state['metricPickedOnCurrentPeriod'] = false;
1098:     this.state['canNavigateForward'] = canPageNewStatsForward(target, this.today);
1099:     this.state['canNavigateBackward'] = true;
1100:     const persistedPeriod: Record<string, Object> = {};
1101:     persistedPeriod['type'] = 'custom';
1102:     persistedPeriod['start'] = target.start;
1103:     persistedPeriod['end'] = target.end;
1104:     this.state['persistedPeriod'] = persistedPeriod;
1105:     this.syncChartStateAfterPeriodChange(false);
1106:     this.recomputeChartSeries();
1107:     await this.emit({
1108:       name: 'commitChartBucketPeriod',
1109:       siteId: this.siteId,
1110:       customStart: target.start,
1111:       customEnd: target.end,
1112:       originPeriodType: 'custom',
1113:       origin: 'custom'
1114:     });
1115:     await this.fetchPeriodData(event);
1116:   }
