1118:   private async pagePeriod(direction: number, event: Record<string, Object>): Promise<void> {
1119:     const period: NewStatsPeriod = this.readCommittedPeriod();
1120:     let next: NewStatsPeriod | undefined;
1121:     if (direction > 0) {
1122:       next = pageNewStatsForward(period, this.today);
1123:     } else {
1124:       next = pageNewStatsBackward(period);
1125:     }
1126:     if (next === undefined) {
1127:       this.state['canNavigateForward'] = false;
1128:       await this.emit({ name: 'pageStatsPeriod', result: 'blocked_at_present_edge', siteId: this.siteId });
1129:       return;
1130:     }
1131:     this.commitPeriod(next);
1132:     this.state['metricPickedOnCurrentPeriod'] = false;
1133:     this.syncChartStateAfterPeriodChange(false);
1134:     this.recomputeChartSeries();
1135:     const after: NewStatsPeriod = this.readCommittedPeriod();
1136:     const paged: Record<string, Object> = {};
1137:     paged['type'] = after.type;
1138:     paged['start'] = after.start;
1139:     paged['end'] = after.end;
1140:     paged['origin'] = after.origin;
1141:     paged['kind'] = after.kind;
1142:     this.state['selectedPeriodAfterNavigation'] = paged;
1143:     this.state['canNavigateForwardAfterNavigation'] = canPageNewStatsForward(after, this.today);
1144:     await this.emit({
1145:       name: 'pageStatsPeriod',
1146:       originPeriodType: after.origin,
1147:       origin: after.origin,
1148:       customStart: after.start,
1149:       customEnd: after.end,
